import groovy.json.JsonSlurper

def request(String method, String url, String body = null, Map headers = [:]) {
  def connection = new URL(url).openConnection()
  connection.requestMethod = method
  connection.connectTimeout = 5000
  connection.readTimeout = 5000
  headers.each { k, v -> connection.setRequestProperty(k, v) }
  if (body != null) {
    connection.doOutput = true
    connection.setRequestProperty('Content-Type', 'application/json')
    connection.outputStream.withWriter('UTF-8') { it << body }
  }
  def status = connection.responseCode
  def text = status >= 400 ? connection.errorStream?.getText('UTF-8') : connection.inputStream?.getText('UTF-8')
  [status: status, body: text ?: '']
}

def services = [
  'API Gateway': context.expand('${#Project#gatewayBaseUrl}'),
  'Auth': context.expand('${#Project#authBaseUrl}'),
  'Product': context.expand('${#Project#productBaseUrl}'),
  'Cart': context.expand('${#Project#cartBaseUrl}'),
  'Order': context.expand('${#Project#orderBaseUrl}'),
  'Inventory': context.expand('${#Project#inventoryBaseUrl}'),
  'Payment': context.expand('${#Project#paymentBaseUrl}'),
  'Notification': context.expand('${#Project#notificationBaseUrl}')
]

services.each { name, baseUrl ->
  def response = request('GET', "${baseUrl}/actuator/health")
  assert response.status == 200 : "${name} health expected 200 but was ${response.status}: ${response.body}"
  assert response.body.contains('"status":"UP"') : "${name} health response should be UP: ${response.body}"
  log.info "${name} health is UP"
}

import groovy.json.JsonOutput
import groovy.json.JsonSlurper

def json = new JsonSlurper()
def baseUrl = context.expand('${#Project#authBaseUrl}')
def email = "soapui.${System.currentTimeMillis()}@example.com"
def password = context.expand('${#Project#customerPassword}')

def request(String method, String url, String body = null, Map headers = [:]) {
  def connection = new URL(url).openConnection()
  connection.requestMethod = method
  connection.connectTimeout = 5000
  connection.readTimeout = 5000
  headers.each { k, v -> connection.setRequestProperty(k, v) }
  if (body != null) {
    connection.doOutput = true
    connection.setRequestProperty('Content-Type', 'application/json')
    connection.outputStream.withWriter('UTF-8') { it << body }
  }
  def status = connection.responseCode
  def text = status >= 400 ? connection.errorStream?.getText('UTF-8') : connection.inputStream?.getText('UTF-8')
  [status: status, body: text ?: '']
}

def registerBody = JsonOutput.toJson([email: email, password: password, role: 'CUSTOMER'])
def registered = request('POST', "${baseUrl}/auth/register", registerBody)
assert registered.status == 200 : registered.body
def token = json.parseText(registered.body).accessToken
assert token
testRunner.testCase.setPropertyValue('accessToken', token)
testRunner.testCase.testSuite.project.setPropertyValue('customerEmail', email)

def duplicate = request('POST', "${baseUrl}/auth/register", registerBody)
assert duplicate.status == 409 : "Duplicate registration should return 409 but was ${duplicate.status}"

def login = request('POST', "${baseUrl}/auth/login", JsonOutput.toJson([email: email, password: password]))
assert login.status == 200 : login.body
assert json.parseText(login.body).accessToken

def invalidLogin = request('POST', "${baseUrl}/auth/login", JsonOutput.toJson([email: email, password: 'wrong-password']))
assert invalidLogin.status == 401 : "Invalid login should return 401 but was ${invalidLogin.status}"

def claims = request('GET', "${baseUrl}/auth/validate", null, ['Authorization': "Bearer ${token}"])
assert claims.status == 200 : claims.body
def claimsJson = json.parseText(claims.body)
assert claimsJson.email == email
assert claimsJson.role == 'CUSTOMER'

import groovy.json.JsonOutput
import groovy.json.JsonSlurper

def json = new JsonSlurper()
def baseUrl = context.expand('${#Project#productBaseUrl}')

def request(String method, String url, String body = null) {
  def connection = new URL(url).openConnection()
  connection.requestMethod = method
  connection.connectTimeout = 5000
  connection.readTimeout = 5000
  if (body != null) {
    connection.doOutput = true
    connection.setRequestProperty('Content-Type', 'application/json')
    connection.outputStream.withWriter('UTF-8') { it << body }
  }
  def status = connection.responseCode
  def text = status >= 400 ? connection.errorStream?.getText('UTF-8') : connection.inputStream?.getText('UTF-8')
  [status: status, body: text ?: '']
}

def list = request('GET', "${baseUrl}/products")
assert list.status == 200 : list.body
assert json.parseText(list.body).size() >= 3

def search = request('GET', "${baseUrl}/products?q=Travel")
assert search.status == 200 : search.body
assert json.parseText(search.body).any { it.category == 'Travel' }

def createBody = JsonOutput.toJson([name: 'SoapUI Keyboard', category: 'Electronics', price: 59.99, description: 'Automated test product'])
def created = request('POST', "${baseUrl}/products", createBody)
assert created.status == 200 : created.body
def product = json.parseText(created.body)
assert product.id
assert product.name == 'SoapUI Keyboard'
testRunner.testCase.setPropertyValue('productId', product.id)
testRunner.testCase.testSuite.project.setPropertyValue('createdProductId', product.id)

def fetched = request('GET', "${baseUrl}/products/${product.id}")
assert fetched.status == 200 : fetched.body
assert json.parseText(fetched.body).id == product.id

def updated = request('PUT', "${baseUrl}/products/${product.id}", JsonOutput.toJson([name: 'SoapUI Keyboard Pro', category: 'Electronics', price: 69.99, description: 'Updated by SoapUI']))
assert updated.status == 200 : updated.body
assert json.parseText(updated.body).name == 'SoapUI Keyboard Pro'

def missingGet = request('GET', "${baseUrl}/products/missing-product")
assert missingGet.status == 404 : "Missing product GET should return 404 but was ${missingGet.status}"

def missingUpdate = request('PUT', "${baseUrl}/products/missing-product", createBody)
assert missingUpdate.status == 404 : "Missing product update should return 404 but was ${missingUpdate.status}"

import groovy.json.JsonOutput
import groovy.json.JsonSlurper

def json = new JsonSlurper()
def baseUrl = context.expand('${#Project#cartBaseUrl}')
def customerId = context.expand('${#Project#customerId}')

def request(String method, String url, String body = null) {
  def connection = new URL(url).openConnection()
  connection.requestMethod = method
  connection.connectTimeout = 5000
  connection.readTimeout = 5000
  if (body != null) {
    connection.doOutput = true
    connection.setRequestProperty('Content-Type', 'application/json')
    connection.outputStream.withWriter('UTF-8') { it << body }
  }
  def status = connection.responseCode
  def text = status >= 400 ? connection.errorStream?.getText('UTF-8') : connection.inputStream?.getText('UTF-8')
  [status: status, body: text ?: '']
}

def empty = request('GET', "${baseUrl}/carts/${customerId}")
assert empty.status == 200 : empty.body
assert json.parseText(empty.body).items.size() == 0

def itemOne = request('POST', "${baseUrl}/carts/${customerId}/items", JsonOutput.toJson([productId: 'demo-laptop', quantity: 1, unitPrice: 799.00]))
assert itemOne.status == 200 : itemOne.body
assert json.parseText(itemOne.body).items.size() == 1

def itemTwo = request('POST', "${baseUrl}/carts/${customerId}/items", JsonOutput.toJson([productId: 'demo-headphones', quantity: 2, unitPrice: 99.00]))
assert itemTwo.status == 200 : itemTwo.body
assert json.parseText(itemTwo.body).items.size() == 2

def invalidItem = request('POST', "${baseUrl}/carts/${customerId}/items", JsonOutput.toJson([productId: '', quantity: 0, unitPrice: -1]))
assert invalidItem.status == 400 : "Invalid cart item should return 400 but was ${invalidItem.status}"

def cleared = request('DELETE', "${baseUrl}/carts/${customerId}")
assert cleared.status == 200 : cleared.body

def afterClear = request('GET', "${baseUrl}/carts/${customerId}")
assert afterClear.status == 200 : afterClear.body
assert json.parseText(afterClear.body).items.size() == 0

import groovy.json.JsonOutput
import groovy.json.JsonSlurper

def json = new JsonSlurper()
def baseUrl = context.expand('${#Project#inventoryBaseUrl}')
def productId = context.expand('${#Project#testProductId}')

def request(String method, String url, String body = null) {
  def connection = new URL(url).openConnection()
  connection.requestMethod = method
  connection.connectTimeout = 5000
  connection.readTimeout = 5000
  if (body != null) {
    connection.doOutput = true
    connection.setRequestProperty('Content-Type', 'application/json')
    connection.outputStream.withWriter('UTF-8') { it << body }
  }
  def status = connection.responseCode
  def text = status >= 400 ? connection.errorStream?.getText('UTF-8') : connection.inputStream?.getText('UTF-8')
  [status: status, body: text ?: '']
}

def list = request('GET', "${baseUrl}/inventory")
assert list.status == 200 : list.body
assert json.parseText(list.body).size() >= 2

def upsert = request('PUT', "${baseUrl}/inventory/${productId}", JsonOutput.toJson([available: 5]))
assert upsert.status == 200 : upsert.body
assert json.parseText(upsert.body).available == 5

def reserveBody = JsonOutput.toJson([orderId: 'soapui-order-reserve', items: [[productId: productId, quantity: 3, unitPrice: 10.00]]])
def reserved = request('POST', "${baseUrl}/inventory/reserve", reserveBody)
assert reserved.status == 200 : reserved.body
def reservation = json.parseText(reserved.body)
assert reservation.reservationId
testRunner.testCase.setPropertyValue('reservationId', reservation.reservationId)

def conflict = request('POST', "${baseUrl}/inventory/reserve", JsonOutput.toJson([orderId: 'soapui-order-conflict', items: [[productId: productId, quantity: 99, unitPrice: 10.00]]]))
assert conflict.status == 409 : "Insufficient stock should return 409 but was ${conflict.status}"

def release = request('POST', "${baseUrl}/inventory/release/${reservation.reservationId}")
assert release.status == 200 : release.body

import groovy.json.JsonOutput
import groovy.json.JsonSlurper

def json = new JsonSlurper()
def baseUrl = context.expand('${#Project#orderBaseUrl}')
def customerId = context.expand('${#Project#customerId}')

def request(String method, String url, String body = null) {
  def connection = new URL(url).openConnection()
  connection.requestMethod = method
  connection.connectTimeout = 5000
  connection.readTimeout = 5000
  if (body != null) {
    connection.doOutput = true
    connection.setRequestProperty('Content-Type', 'application/json')
    connection.outputStream.withWriter('UTF-8') { it << body }
  }
  def status = connection.responseCode
  def text = status >= 400 ? connection.errorStream?.getText('UTF-8') : connection.inputStream?.getText('UTF-8')
  [status: status, body: text ?: '']
}

def list = request('GET', "${baseUrl}/orders")
assert list.status == 200 : list.body

def createBody = JsonOutput.toJson([customerId: customerId, items: [
  [productId: 'demo-laptop', quantity: 1, unitPrice: 799.00],
  [productId: 'demo-headphones', quantity: 2, unitPrice: 99.00]
]])
def created = request('POST', "${baseUrl}/orders", createBody)
assert created.status == 200 : created.body
def order = json.parseText(created.body)
assert order.orderId
assert order.status == 'PENDING'
assert order.total == 997.00
testRunner.testCase.setPropertyValue('orderId', order.orderId)
testRunner.testCase.testSuite.project.setPropertyValue('orderId', order.orderId)

def fetched = request('GET', "${baseUrl}/orders/${order.orderId}")
assert fetched.status == 200 : fetched.body
assert json.parseText(fetched.body).orderId == order.orderId

def confirmed = request('POST', "${baseUrl}/orders/${order.orderId}/confirm")
assert confirmed.status == 200 : confirmed.body
assert json.parseText(confirmed.body).status == 'CONFIRMED'

def cancelled = request('POST', "${baseUrl}/orders/${order.orderId}/cancel", JsonOutput.toJson([reason: 'SoapUI cancellation test']))
assert cancelled.status == 200 : cancelled.body
assert json.parseText(cancelled.body).status == 'CANCELLED'

def missing = request('GET', "${baseUrl}/orders/missing-order")
assert missing.status == 404 : "Missing order should return 404 but was ${missing.status}"

import groovy.json.JsonOutput
import groovy.json.JsonSlurper

def json = new JsonSlurper()
def baseUrl = context.expand('${#Project#paymentBaseUrl}')

def request(String method, String url, String body = null) {
  def connection = new URL(url).openConnection()
  connection.requestMethod = method
  connection.connectTimeout = 5000
  connection.readTimeout = 5000
  if (body != null) {
    connection.doOutput = true
    connection.setRequestProperty('Content-Type', 'application/json')
    connection.outputStream.withWriter('UTF-8') { it << body }
  }
  def status = connection.responseCode
  def text = status >= 400 ? connection.errorStream?.getText('UTF-8') : connection.inputStream?.getText('UTF-8')
  [status: status, body: text ?: '']
