def invalid = request('POST', "${baseUrl}/payments", JsonOutput.toJson([orderId: '', amount: -1, forceFailure: false]))
assert invalid.status == 400 : "Invalid payment should return 400 but was ${invalid.status}"

def list = request('GET', "${baseUrl}/payments")
assert list.status == 200 : list.body
assert json.parseText(list.body).size() >= 2

import groovy.json.JsonOutput
import groovy.json.JsonSlurper

def json = new JsonSlurper()
def baseUrl = context.expand('${#Project#notificationBaseUrl}')
def customerId = context.expand('${#Project#customerId}')

def request(String method, String url, String body = null) {
  def connection = new URL(url).openConnection()
  connection.requestMethod = method
  connection.connectTimeout = 5000
  connection.readTimeout = 5000
  if (body != null) {
    connection.doOutput = true
    connection.setRequestProperty('Content-Type', 'application/json')
    connection.outputStream.withWriter('UTF-8') { it << body }
  }
  def status = connection.responseCode
  def text = status >= 400 ? connection.errorStream?.getText('UTF-8') : connection.inputStream?.getText('UTF-8')
  [status: status, body: text ?: '']
}

def sent = request('POST', "${baseUrl}/notifications", JsonOutput.toJson([customerId: customerId, channel: 'EMAIL', subject: 'Order confirmed', body: 'Your order has been confirmed.']))
assert sent.status == 200 : sent.body
def message = json.parseText(sent.body)
assert message.notificationId
assert message.status == 'SENT'
assert message.channel == 'EMAIL'

def invalid = request('POST', "${baseUrl}/notifications", JsonOutput.toJson([customerId: '', channel: '', subject: '', body: '']))
assert invalid.status == 400 : "Invalid notification should return 400 but was ${invalid.status}"

def list = request('GET', "${baseUrl}/notifications")
assert list.status == 200 : list.body
assert json.parseText(list.body).size() >= 1

import groovy.json.JsonOutput
import groovy.json.JsonSlurper

def json = new JsonSlurper()
def baseUrl = context.expand('${#Project#gatewayBaseUrl}')

def request(String method, String url, String body = null) {
  def connection = new URL(url).openConnection()
  connection.requestMethod = method
  connection.connectTimeout = 5000
  connection.readTimeout = 5000
  if (body != null) {
    connection.doOutput = true
    connection.setRequestProperty('Content-Type', 'application/json')
    connection.outputStream.withWriter('UTF-8') { it << body }
  }
  def status = connection.responseCode
  def text = status >= 400 ? connection.errorStream?.getText('UTF-8') : connection.inputStream?.getText('UTF-8')
  [status: status, body: text ?: '', gateway: connection.getHeaderField('X-Gateway')]
}

def products = request('GET', "${baseUrl}/products")
assert products.status == 200 : products.body
assert products.gateway == 'ecommerce-api-gateway'
assert json.parseText(products.body).size() >= 3

def cart = request('GET', "${baseUrl}/carts/gateway-customer")
assert cart.status == 200 : cart.body
assert cart.gateway == 'ecommerce-api-gateway'

def notification = request('POST', "${baseUrl}/notifications", JsonOutput.toJson([customerId: 'gateway-customer', channel: 'SMS', subject: 'Gateway test', body: 'Gateway routed notification']))
assert notification.status == 200 : notification.body
assert notification.gateway == 'ecommerce-api-gateway'

import groovy.json.JsonOutput
import groovy.json.JsonSlurper

def json = new JsonSlurper()
def inventoryUrl = context.expand('${#Project#inventoryBaseUrl}')
def orderUrl = context.expand('${#Project#orderBaseUrl}')
def paymentUrl = context.expand('${#Project#paymentBaseUrl}')
def notificationUrl = context.expand('${#Project#notificationBaseUrl}')
def customerId = context.expand('${#Project#customerId}')
def productId = 'soapui-checkout-product'

def request(String method, String url, String body = null) {
  def connection = new URL(url).openConnection()
  connection.requestMethod = method
  connection.connectTimeout = 5000
  connection.readTimeout = 5000
  if (body != null) {
    connection.doOutput = true
    connection.setRequestProperty('Content-Type', 'application/json')
    connection.outputStream.withWriter('UTF-8') { it << body }
  }
  def status = connection.responseCode
  def text = status >= 400 ? connection.errorStream?.getText('UTF-8') : connection.inputStream?.getText('UTF-8')
  [status: status, body: text ?: '']
}

assert request('PUT', "${inventoryUrl}/inventory/${productId}", JsonOutput.toJson([available: 10])).status == 200

def orderBody = JsonOutput.toJson([customerId: customerId, items: [[productId: productId, quantity: 2, unitPrice: 25.00]]])
def orderResponse = request('POST', "${orderUrl}/orders", orderBody)
assert orderResponse.status == 200 : orderResponse.body
def order = json.parseText(orderResponse.body)
assert order.status == 'PENDING'
assert order.total == 50.00

def reserveResponse = request('POST', "${inventoryUrl}/inventory/reserve", JsonOutput.toJson([orderId: order.orderId, items: order.items]))
assert reserveResponse.status == 200 : reserveResponse.body
def reservation = json.parseText(reserveResponse.body)
assert reservation.reservationId

def paymentResponse = request('POST', "${paymentUrl}/payments", JsonOutput.toJson([orderId: order.orderId, amount: order.total, forceFailure: false]))
assert paymentResponse.status == 200 : paymentResponse.body
assert json.parseText(paymentResponse.body).status == 'SUCCEEDED'

def confirmResponse = request('POST', "${orderUrl}/orders/${order.orderId}/confirm")
assert confirmResponse.status == 200 : confirmResponse.body
assert json.parseText(confirmResponse.body).status == 'CONFIRMED'

def notifyResponse = request('POST', "${notificationUrl}/notifications", JsonOutput.toJson([customerId: customerId, channel: 'EMAIL', subject: 'Order confirmed', body: "Order ${order.orderId} is confirmed."]))
assert notifyResponse.status == 200 : notifyResponse.body
assert json.parseText(notifyResponse.body).status == 'SENT'

import groovy.json.JsonOutput
import groovy.json.JsonSlurper

def json = new JsonSlurper()
def inventoryUrl = context.expand('${#Project#inventoryBaseUrl}')
def orderUrl = context.expand('${#Project#orderBaseUrl}')
def paymentUrl = context.expand('${#Project#paymentBaseUrl}')
def notificationUrl = context.expand('${#Project#notificationBaseUrl}')
def customerId = context.expand('${#Project#customerId}')
def productId = 'soapui-compensation-product'

def request(String method, String url, String body = null) {
  def connection = new URL(url).openConnection()
  connection.requestMethod = method
  connection.connectTimeout = 5000
  connection.readTimeout = 5000
  if (body != null) {
    connection.doOutput = true
    connection.setRequestProperty('Content-Type', 'application/json')
    connection.outputStream.withWriter('UTF-8') { it << body }
  }
  def status = connection.responseCode
  def text = status >= 400 ? connection.errorStream?.getText('UTF-8') : connection.inputStream?.getText('UTF-8')
  [status: status, body: text ?: '']
}

assert request('PUT', "${inventoryUrl}/inventory/${productId}", JsonOutput.toJson([available: 4])).status == 200

def orderResponse = request('POST', "${orderUrl}/orders", JsonOutput.toJson([customerId: customerId, items: [[productId: productId, quantity: 2, unitPrice: 30.00]]]))
assert orderResponse.status == 200 : orderResponse.body
def order = json.parseText(orderResponse.body)

def reserveResponse = request('POST', "${inventoryUrl}/inventory/reserve", JsonOutput.toJson([orderId: order.orderId, items: order.items]))
assert reserveResponse.status == 200 : reserveResponse.body
def reservation = json.parseText(reserveResponse.body)

def paymentResponse = request('POST', "${paymentUrl}/payments", JsonOutput.toJson([orderId: order.orderId, amount: order.total, forceFailure: true]))
assert paymentResponse.status == 200 : paymentResponse.body
assert json.parseText(paymentResponse.body).status == 'FAILED'

def releaseResponse = request('POST', "${inventoryUrl}/inventory/release/${reservation.reservationId}")
assert releaseResponse.status == 200 : releaseResponse.body

def cancelResponse = request('POST', "${orderUrl}/orders/${order.orderId}/cancel", JsonOutput.toJson([reason: 'Payment failed']))
assert cancelResponse.status == 200 : cancelResponse.body
assert json.parseText(cancelResponse.body).status == 'CANCELLED'

def notifyResponse = request('POST', "${notificationUrl}/notifications", JsonOutput.toJson([customerId: customerId, channel: 'EMAIL', subject: 'Payment failed', body: "Order ${order.orderId} was cancelled because payment failed."]))
assert notifyResponse.status == 200 : notifyResponse.body
assert json.parseText(notifyResponse.body).status == 'SENT'
